//! `doxa native init`: makes the web crate buildable as a native app, leaving what's there.

use std::path::Path;

use doxa_build::config::Workspace;
use toml_edit::{value, Array, DocumentMut, InlineTable, Item, Table};

type Error = Box<dyn std::error::Error>;

const ICON: &[u8] = include_bytes!("../../templates/native/icon.png");
const BUILD_RS: &str = "fn main() {\n    doxa_role::client()\n}\n";
const IGNORED: &[&str] = &[
    "/tauri.conf.json",
    "/icons/",
    "/gen/",
    "/permissions/autogenerated/",
    "/.cargo/config.toml",
];
const NATIVE_TARGET: &str = "cfg(not(target_arch = \"wasm32\"))";

/// What the edit to `Cargo.toml` needs to know.
struct Crate<'a> {
    name: &'a str,
    /// Whether its doxa dependency is `workspace = true`, as inside doxa's own repo.
    workspace: bool,
}

pub fn run(cwd: &Path) -> Result<(), Error> {
    let ws = Workspace::load(cwd)?;
    let web = ws.web_crate(None)?;
    let dir = &web.dir;
    let manifest = dir.join("Cargo.toml");
    let text = std::fs::read_to_string(&manifest)?;
    let mut doc: DocumentMut = text.parse()?;
    let workspace = doc
        .get("dependencies")
        .and_then(|d| d.get("doxa"))
        .and_then(|d| d.get("workspace"))
        .and_then(Item::as_bool)
        .unwrap_or(false);
    edit(
        &mut doc,
        &Crate {
            name: &web.name,
            workspace,
        },
    );
    let edited = doc.to_string();
    if edited != text {
        std::fs::write(&manifest, edited)?;
        eprintln!(
            "[doxa] {}: added the native feature, bin and config",
            manifest.display()
        );
    }
    let api = web.config.server.as_deref().map(|s| s.replace('-', "_"));
    let lib = dir.join("src/lib.rs");
    let lib_text = std::fs::read_to_string(&lib)?;
    if !lib_text.contains("#[doxa::app]") {
        let local = match &api {
            Some(api) => format!("\n        .local({api}::server::start)"),
            None => String::new(),
        };
        let stub = format!(
            "\n/// The native app; `doxa build --desktop` bundles it.\n#[doxa::app]\nfn native_app() -> doxa_native::App {{\n    doxa_native::App::new(){local}\n}}\n"
        );
        std::fs::write(&lib, lib_text + &stub)?;
        eprintln!("[doxa] {}: added the `#[doxa::app]` entry", lib.display());
    }
    write_new(&dir.join("build.rs"), BUILD_RS.as_bytes())?;
    let build = std::fs::read_to_string(dir.join("build.rs"))?;
    if !build.contains("doxa_role::client") && !build.contains("doxa_role::Client") {
        eprintln!(
            "[doxa] build.rs: call `doxa_role::client()` from it, which builds the native shell"
        );
    }
    let main = format!("fn main() {{\n    {}::__app_main()\n}}\n", web.lib_name);
    write_new(&dir.join("src/main.rs"), main.as_bytes())?;
    write_new(&dir.join("native/icon.png"), ICON)?;
    ignore(&dir.join(".gitignore"))?;
    if let Some(api) = &api {
        eprintln!(
            "[doxa] the native app serves `{api}::server::start(stop)`: what the api's `#[doxa::main] start` \
             builds, moved into its server module so both can call it"
        );
    }
    eprintln!(
        "[doxa] set `identifier` in [package.metadata.doxa.native], then `doxa build --desktop`"
    );
    Ok(())
}

fn edit(doc: &mut DocumentMut, c: &Crate) {
    let lib = table(doc.as_table_mut(), "lib");
    let types = lib
        .entry("crate-type")
        .or_insert(value(Array::new()))
        .as_array_mut();
    if let Some(types) = types {
        // `staticlib` is what the iOS app links.
        for t in ["cdylib", "rlib", "staticlib"] {
            if !types.iter().any(|v| v.as_str() == Some(t)) {
                types.push(t);
            }
        }
    }
    let bins = doc
        .entry("bin")
        .or_insert(Item::ArrayOfTables(Default::default()));
    if let Some(bins) = bins.as_array_of_tables_mut() {
        let has = bins
            .iter()
            .any(|b| b.get("path").and_then(Item::as_str) == Some("src/main.rs"));
        if !has {
            let mut bin = Table::new();
            bin["name"] = value(c.name);
            bin["path"] = value("src/main.rs");
            bin["required-features"] = value(Array::from_iter(["native"]));
            bins.push(bin);
        }
    }
    let features = table(doc.as_table_mut(), "features");
    if !features.contains_key("native") {
        features["native"] = value(Array::from_iter(["dep:doxa-native", "dep:tauri"]));
    }
    let deps = table(
        table(table(doc.as_table_mut(), "target"), NATIVE_TARGET),
        "dependencies",
    );
    if !deps.contains_key("doxa-native") {
        deps["doxa-native"] = value(dep(c.workspace, None));
    }
    if !deps.contains_key("tauri") {
        let mut t = InlineTable::new();
        t.insert("version", "2.12".into());
        t.insert("optional", true.into());
        // The Tauri CLI rewrites this list to what the config needs; present, it stays tidy.
        t.insert("features", Array::new().into());
        deps["tauri"] = value(t);
    }
    let build = table(doc.as_table_mut(), "build-dependencies");
    match build.get_mut("doxa-role") {
        None => build["doxa-role"] = value(dep(c.workspace, Some("native-build"))),
        Some(role) => add_feature(role, "native-build"),
    }
    if let Some(doxa) = table(doc.as_table_mut(), "dependencies").get_mut("doxa") {
        add_feature(doxa, "native");
    }
    let doxa = table(
        table(table(doc.as_table_mut(), "package"), "metadata"),
        "doxa",
    );
    if !doxa.contains_key("native") {
        let mut native = Table::new();
        native["identifier"] = value(identifier(c.name));
        native["server"] = value("local");
        doxa["native"] = Item::Table(native);
    }
}

/// `com.example.<name>`, with what an identifier segment can't hold replaced.
fn identifier(name: &str) -> String {
    let seg: String = name
        .to_ascii_lowercase()
        .chars()
        .map(|c| if c.is_ascii_alphanumeric() { c } else { '_' })
        .collect();
    let seg = match seg.chars().next() {
        Some(c) if c.is_ascii_alphabetic() => seg,
        _ => format!("app_{seg}"),
    };
    format!("com.example.{seg}")
}

fn dep(workspace: bool, feature: Option<&str>) -> InlineTable {
    let mut t = InlineTable::new();
    if workspace {
        t.insert("workspace", true.into());
    } else {
        t.insert("version", env!("CARGO_PKG_VERSION").into());
    }
    match feature {
        Some(f) => {
            t.insert("features", Array::from_iter([f]).into());
        }
        None => {
            t.insert("optional", true.into());
        }
    }
    t
}

/// Turns `feature` on in a dependency, written as a version string or a table.
fn add_feature(dep: &mut Item, feature: &str) {
    if let Some(v) = dep.as_str().map(str::to_owned) {
        let mut t = InlineTable::new();
        t.insert("version", v.into());
        *dep = value(t);
    }
    let features = dep.as_table_like_mut().and_then(|t| {
        t.entry("features")
            .or_insert(value(Array::new()))
            .as_array_mut()
    });
    if let Some(f) = features {
        if !f.iter().any(|v| v.as_str() == Some(feature)) {
            f.push(feature);
        }
    }
}

/// The table at `key`, made if absent.
fn table<'a>(parent: &'a mut Table, key: &str) -> &'a mut Table {
    let item = parent.entry(key).or_insert_with(|| {
        let mut t = Table::new();
        t.set_implicit(true);
        Item::Table(t)
    });
    item.as_table_mut()
        .unwrap_or_else(|| panic!("`{key}` in Cargo.toml isn't a table"))
}

fn write_new(path: &Path, content: &[u8]) -> std::io::Result<()> {
    if path.exists() {
        return Ok(());
    }
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(path, content)?;
    eprintln!("[doxa] wrote {}", path.display());
    Ok(())
}

fn ignore(path: &Path) -> std::io::Result<()> {
    let text = std::fs::read_to_string(path).unwrap_or_default();
    let missing: Vec<&str> = IGNORED
        .iter()
        .copied()
        .filter(|l| !text.lines().any(|t| t.trim() == *l))
        .collect();
    if missing.is_empty() {
        return Ok(());
    }
    let mut out = text;
    if !out.is_empty() && !out.ends_with('\n') {
        out.push('\n');
    }
    out.push_str("# Generated by doxa for native builds.\n");
    for l in missing {
        out.push_str(l);
        out.push('\n');
    }
    std::fs::write(path, out)
}

#[cfg(test)]
mod tests {
    use super::*;

    const WEB: &str = r#"[package]
name = "shop-web"
version = "0.1.0"

[lib]
crate-type = ["cdylib", "rlib"]

[package.metadata.doxa]
role = "client"
server = "shop-api"

[dependencies]
# kept
doxa = { version = "0.1", features = ["ui"] }

[build-dependencies]
doxa-role = "0.1"
"#;

    fn edited(src: &str, workspace: bool) -> String {
        let mut doc: DocumentMut = src.parse().unwrap();
        edit(
            &mut doc,
            &Crate {
                name: "shop-web",
                workspace,
            },
        );
        doc.to_string()
    }

    #[test]
    fn adds_the_feature_bin_deps_and_config_and_keeps_the_rest() {
        let out = edited(WEB, false);
        let doc: toml::Table = out.parse().unwrap();
        assert!(out.contains("# kept"));
        assert_eq!(doc["features"]["native"].as_array().unwrap().len(), 2);
        let bin = &doc["bin"].as_array().unwrap()[0];
        assert_eq!(bin["name"].as_str(), Some("shop-web"));
        assert_eq!(bin["required-features"][0].as_str(), Some("native"));
        let deps = &doc["target"][NATIVE_TARGET]["dependencies"];
        assert_eq!(deps["doxa-native"]["optional"].as_bool(), Some(true));
        assert_eq!(deps["tauri"]["version"].as_str(), Some("2.12"));
        assert!(deps["tauri"]["features"].as_array().unwrap().is_empty());
        let role = &doc["build-dependencies"]["doxa-role"];
        assert_eq!(role["version"].as_str(), Some("0.1"));
        assert_eq!(role["features"][0].as_str(), Some("native-build"));
        let doxa = doc["dependencies"]["doxa"]["features"].as_array().unwrap();
        assert_eq!(
            doxa.iter().filter_map(|f| f.as_str()).collect::<Vec<_>>(),
            ["ui", "native"]
        );
        let native = &doc["package"]["metadata"]["doxa"]["native"];
        assert_eq!(native["identifier"].as_str(), Some("com.example.shop_web"));
        assert_eq!(native["server"].as_str(), Some("local"));
        assert!(doxa_build::native::NativeConfig::from_manifest(&out)
            .unwrap()
            .is_some());
    }

    #[test]
    fn running_twice_changes_nothing_more() {
        let once = edited(WEB, true);
        assert_eq!(edited(&once, true), once);
        assert!(once.contains("doxa-native = { workspace = true, optional = true }"));
    }

    #[test]
    fn an_identifier_is_always_valid() {
        assert_eq!(identifier("Shop-Web"), "com.example.shop_web");
        assert_eq!(identifier("9lives"), "com.example.app_9lives");
    }
}
